    :root {
        --direction-multiplier: 1
    }

    .elementor-screen-only {
        height: 1px;
        margin: -1px;
        overflow: hidden;
        padding: 0;
        position: absolute;
        top: -10000em;
        width: 1px;
        clip: rect(0, 0, 0, 0);
        border: 0
    }

    .elementor *,
    .elementor :after,
    .elementor :before {
        box-sizing: border-box
    }

    .elementor a {
        box-shadow: none;
        text-decoration: none
    }

    .elementor img {
        border: none;
        border-radius: 0;
        box-shadow: none;
        height: auto;
        max-width: 100%
    }

    .elementor .elementor-widget:not(.elementor-widget-text-editor):not(.elementor-widget-theme-post-content) figure {
        margin: 0
    }

    .e-con>.elementor-element.elementor-absolute {
        position: absolute
    }

    .elementor-element.elementor-absolute {
        z-index: 1
    }

    .elementor-element {
        --flex-direction: initial;
        --flex-wrap: initial;
        --justify-content: initial;
        --align-items: initial;
        --align-content: initial;
        --gap: initial;
        --flex-basis: initial;
        --flex-grow: initial;
        --flex-shrink: initial;
        --order: initial;
        --align-self: initial;
        align-self: var(--align-self);
        flex-basis: var(--flex-basis);
        flex-grow: var(--flex-grow);
        flex-shrink: var(--flex-shrink);
        order: var(--order)
    }

    .elementor-invisible {
        visibility: hidden
    }

    .elementor-align-center {
        text-align: center
    }

    .elementor-align-center .elementor-button {
        width: auto
    }

    @media (max-width:767px) {
        .elementor-mobile-align-center {
            text-align: center
        }
    }

    :root {
        --page-title-display: block
    }

    .elementor-section {
        position: relative
    }

    .elementor-section .elementor-container {
        display: flex;
        margin-inline: auto;
        position: relative
    }

    @media (max-width:1024px) {
        .elementor-section .elementor-container {
            flex-wrap: wrap
        }
    }

    .elementor-widget-wrap {
        align-content: flex-start;
        flex-wrap: wrap;
        position: relative;
        width: 100%
    }

    .elementor:not(.elementor-bc-flex-widget) .elementor-widget-wrap {
        display: flex
    }

    .elementor-widget-wrap>.elementor-element {
        width: 100%
    }

    .elementor-widget {
        position: relative
    }

    .elementor-widget:not(:last-child) {
        margin-block-end: var(--kit-widget-spacing, 20px)
    }

    .elementor-widget:not(:last-child).elementor-widget__width-initial {
        margin-block-end: 0
    }

    .elementor-column {
        display: flex;
        min-height: 1px;
        position: relative
    }

    .elementor-column-gap-default>.elementor-column>.elementor-element-populated {
        padding: 10px
    }

    @media (min-width:768px) {
        .elementor-column.elementor-col-100 {
            width: 100%
        }
    }

    @media (max-width:767px) {
        .elementor-column {
            width: 100%
        }
    }

    @media (prefers-reduced-motion:no-preference) {
        html {
            scroll-behavior: smooth
        }
    }

    .e-con {
        --border-radius: 0;
        --border-top-width: 0px;
        --border-right-width: 0px;
        --border-bottom-width: 0px;
        --border-left-width: 0px;
        --border-style: initial;
        --border-color: initial;
        --container-widget-width: 100%;
        --container-widget-height: initial;
        --container-widget-flex-grow: 0;
        --container-widget-align-self: initial;
        --content-width: min(100%, var(--container-max-width, 1140px));
        --width: 100%;
        --min-height: initial;
        --height: auto;
        --text-align: initial;
        --margin-top: 0px;
        --margin-right: 0px;
        --margin-bottom: 0px;
        --margin-left: 0px;
        --padding-top: var(--container-default-padding-top, 10px);
        --padding-right: var(--container-default-padding-right, 10px);
        --padding-bottom: var(--container-default-padding-bottom, 10px);
        --padding-left: var(--container-default-padding-left, 10px);
        --position: relative;
        --z-index: revert;
        --overflow: visible;
        --gap: var(--widgets-spacing, 20px);
        --row-gap: var(--widgets-spacing-row, 20px);
        --column-gap: var(--widgets-spacing-column, 20px);
        --overlay-mix-blend-mode: initial;
        --overlay-opacity: 1;
        --e-con-grid-template-columns: repeat(3, 1fr);
        --e-con-grid-template-rows: repeat(2, 1fr);
        border-radius: var(--border-radius);
        height: var(--height);
        min-height: var(--min-height);
        min-width: 0;
        overflow: var(--overflow);
        position: var(--position);
        width: var(--width);
        z-index: var(--z-index);
        --flex-wrap-mobile: wrap
    }

    .e-con {
        --margin-block-start: var(--margin-top);
        --margin-block-end: var(--margin-bottom);
        --margin-inline-start: var(--margin-left);
        --margin-inline-end: var(--margin-right);
        --padding-inline-start: var(--padding-left);
        --padding-inline-end: var(--padding-right);
        --padding-block-start: var(--padding-top);
        --padding-block-end: var(--padding-bottom);
        --border-block-start-width: var(--border-top-width);
        --border-block-end-width: var(--border-bottom-width);
        --border-inline-start-width: var(--border-left-width);
        --border-inline-end-width: var(--border-right-width)
    }

    .e-con {
        margin-block-end: var(--margin-block-end);
        margin-block-start: var(--margin-block-start);
        margin-inline-end: var(--margin-inline-end);
        margin-inline-start: var(--margin-inline-start);
        padding-inline-end: var(--padding-inline-end);
        padding-inline-start: var(--padding-inline-start)
    }

    .e-con.e-flex {
        --flex-direction: column;
        --flex-basis: auto;
        --flex-grow: 0;
        --flex-shrink: 1;
        flex: var(--flex-grow) var(--flex-shrink) var(--flex-basis)
    }

    .e-con-full,
    .e-con>.e-con-inner {
        padding-block-end: var(--padding-block-end);
        padding-block-start: var(--padding-block-start);
        text-align: var(--text-align)
    }

    .e-con-full.e-flex,
    .e-con.e-flex>.e-con-inner {
        flex-direction: var(--flex-direction)
    }

    .e-con,
    .e-con>.e-con-inner {
        display: var(--display)
    }

    .e-con-boxed.e-flex {
        align-content: normal;
        align-items: normal;
        flex-direction: column;
        flex-wrap: nowrap;
        justify-content: normal
    }

    .e-con-boxed {
        gap: initial;
        text-align: initial
    }

    .e-con.e-flex>.e-con-inner {
        align-content: var(--align-content);
        align-items: var(--align-items);
        align-self: auto;
        flex-basis: auto;
        flex-grow: 1;
        flex-shrink: 1;
        flex-wrap: var(--flex-wrap);
        justify-content: var(--justify-content)
    }

    .e-con>.e-con-inner {
        gap: var(--row-gap) var(--column-gap);
        height: 100%;
        margin: 0 auto;
        max-width: var(--content-width);
        padding-inline-end: 0;
        padding-inline-start: 0;
        width: 100%
    }

    .e-con .elementor-widget.elementor-widget {
        margin-block-end: 0
    }

    .e-con:before {
        border-block-end-width: var(--border-block-end-width);
        border-block-start-width: var(--border-block-start-width);
        border-color: var(--border-color);
        border-inline-end-width: var(--border-inline-end-width);
        border-inline-start-width: var(--border-inline-start-width);
        border-radius: var(--border-radius);
        border-style: var(--border-style);
        content: var(--background-overlay);
        display: block;
        height: max(100% + var(--border-top-width) + var(--border-bottom-width), 100%);
        left: calc(0px - var(--border-left-width));
        mix-blend-mode: var(--overlay-mix-blend-mode);
        opacity: var(--overlay-opacity);
        position: absolute;
        top: calc(0px - var(--border-top-width));
        width: max(100% + var(--border-left-width) + var(--border-right-width), 100%)
    }

    .e-con .elementor-widget {
        min-width: 0
    }

    .e-con>.e-con-inner>.elementor-widget>.elementor-widget-container,
    .e-con>.elementor-widget>.elementor-widget-container {
        height: 100%
    }

    .e-con.e-con>.e-con-inner>.elementor-widget,
    .elementor.elementor .e-con>.elementor-widget {
        max-width: 100%
    }

    .e-con .elementor-widget:not(:last-child) {
        --kit-widget-spacing: 0px
    }

    @media (max-width:767px) {
        .e-con.e-flex {
            --width: 100%;
            --flex-wrap: var(--flex-wrap-mobile)
        }
    }

    .elementor-heading-title {
        line-height: 1;
        margin: 0;
        padding: 0
    }

    .elementor-button {
        background-color: #69727d;
        border-radius: 3px;
        color: #fff;
        display: inline-block;
        fill: #fff;
        font-size: 15px;
        line-height: 1;
        padding: 12px 24px;
        text-align: center
    }

    .elementor-button:visited {
        color: #fff
    }

    .elementor-button-content-wrapper {
        display: flex;
        flex-direction: row;
        gap: 5px;
        justify-content: center
    }

    .elementor-button-icon {
        align-items: center;
        display: flex
    }

    .elementor-button-icon svg {
        height: auto;
        width: 1em
    }

    .elementor-button-icon .e-font-icon-svg {
        height: 1em
    }

    .elementor-button-text {
        display: inline-block
    }

    .elementor-button.elementor-size-md {
        border-radius: 4px;
        font-size: 16px;
        padding: 15px 30px
    }

    .elementor-button span {
        text-decoration: inherit
    }

    .elementor-icon {
        color: #69727d;
        display: inline-block;
        font-size: 50px;
        line-height: 1;
        text-align: center
    }

    .elementor-icon svg {
        display: block;
        height: 1em;
        position: relative;
        width: 1em
    }

    .elementor-icon svg:before {
        left: 50%;
        position: absolute;
        transform: translateX(-50%)
    }

    @media (max-width:767px) {
        .elementor .elementor-hidden-mobile {
            display: none
        }
    }

    @media (min-width:768px) and (max-width:1024px) {
        .elementor .elementor-hidden-tablet {
            display: none
        }
    }

    @media (min-width:1025px) and (max-width:99999px) {
        .elementor .elementor-hidden-desktop {
            display: none
        }
    }

    .elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a {
        color: inherit;
        font-size: inherit;
        line-height: inherit
    }

    .ob-has-background-overlay {
        position: relative
    }

    .ob-has-background-overlay:before {
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        z-index: -1
    }

    .ob-has-background-overlay:after {
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        z-index: -1
    }

    .elementor-widget-icon {
        line-height: 0
    }

    .elementor-widget-image,
    .elementor-widget-image>div,
    .elementor-widget-image img {
        line-height: 0
    }

    .elementor-widget-image {
        text-align: center
    }

    .elementor-widget-image a {
        display: inline-block
    }

    .elementor-widget-image a img[src$=".svg"] {
        width: 48px
    }

    .elementor-widget-image img {
        display: inline-block;
        vertical-align: middle
    }

    .elementor-widget .elementor-icon-list-items {
        list-style-type: none;
        margin: 0;
        padding: 0
    }

    .elementor-widget .elementor-icon-list-item {
        margin: 0;
        padding: 0;
        position: relative
    }

    .elementor-widget .elementor-icon-list-item:after {
        inset-block-end: 0;
        position: absolute;
        width: 100%
    }

    .elementor-widget .elementor-icon-list-item,
    .elementor-widget .elementor-icon-list-item a {
        align-items: var(--icon-vertical-align, center);
        display: flex;
        font-size: inherit
    }

    .elementor-widget .elementor-icon-list-icon+.elementor-icon-list-text {
        align-self: center;
        padding-inline-start: 5px
    }

    .elementor-widget .elementor-icon-list-icon {
        display: flex;
        inset-block-start: var(--icon-vertical-offset, initial);
        position: relative
    }

    .elementor-widget .elementor-icon-list-icon svg {
        height: var(--e-icon-list-icon-size, 1em);
        width: var(--e-icon-list-icon-size, 1em)
    }

    .elementor-widget.elementor-widget-icon-list .elementor-icon-list-icon {
        text-align: var(--e-icon-list-icon-align)
    }

    .elementor-widget.elementor-widget-icon-list .elementor-icon-list-icon svg {
        margin: var(--e-icon-list-icon-margin, 0 calc(var(--e-icon-list-icon-size, 1em) * .25) 0 0)
    }

    .elementor-widget.elementor-align-end .elementor-icon-list-item,
    .elementor-widget.elementor-align-end .elementor-icon-list-item a {
        justify-content: end;
        text-align: end
    }

    .elementor-widget.elementor-align-end .elementor-icon-list-items {
        justify-content: end
    }

    .elementor-widget:not(.elementor-align-start) .elementor-icon-list-item:after {
        inset-inline-end: 0
    }

    @media (min-width:-1) {
        .elementor-widget:not(.elementor-widescreen-align-end) .elementor-icon-list-item:after {
            inset-inline-start: 0
        }

        .elementor-widget:not(.elementor-widescreen-align-start) .elementor-icon-list-item:after {
            inset-inline-end: 0
        }
    }

    @media (max-width:-1) {
        .elementor-widget:not(.elementor-laptop-align-end) .elementor-icon-list-item:after {
            inset-inline-start: 0
        }

        .elementor-widget:not(.elementor-laptop-align-start) .elementor-icon-list-item:after {
            inset-inline-end: 0
        }

        .elementor-widget:not(.elementor-tablet_extra-align-end) .elementor-icon-list-item:after {
            inset-inline-start: 0
        }

        .elementor-widget:not(.elementor-tablet_extra-align-start) .elementor-icon-list-item:after {
            inset-inline-end: 0
        }
    }

    @media (max-width:1024px) {
        .elementor-widget:not(.elementor-tablet-align-end) .elementor-icon-list-item:after {
            inset-inline-start: 0
        }

        .elementor-widget:not(.elementor-tablet-align-start) .elementor-icon-list-item:after {
            inset-inline-end: 0
        }
    }

    @media (max-width:-1) {
        .elementor-widget:not(.elementor-mobile_extra-align-end) .elementor-icon-list-item:after {
            inset-inline-start: 0
        }

        .elementor-widget:not(.elementor-mobile_extra-align-start) .elementor-icon-list-item:after {
            inset-inline-end: 0
        }
    }

    @media (max-width:767px) {

        .elementor-widget.elementor-mobile-align-center .elementor-icon-list-item,
        .elementor-widget.elementor-mobile-align-center .elementor-icon-list-item a {
            justify-content: center
        }

        .elementor-widget.elementor-mobile-align-center .elementor-icon-list-item:after {
            margin: auto
        }

        .elementor-widget:not(.elementor-mobile-align-end) .elementor-icon-list-item:after {
            inset-inline-start: 0
        }

        .elementor-widget:not(.elementor-mobile-align-start) .elementor-icon-list-item:after {
            inset-inline-end: 0
        }
    }

    .elementor .elementor-element ul.elementor-icon-list-items {
        padding: 0
    }

    .elementor-image-gallery .gallery-item {
        display: inline-block;
        margin: 0 auto;
        max-width: 100%;
        text-align: center;
        vertical-align: top;
        width: 100%
    }

    .elementor-image-gallery .gallery-item img {
        margin: 0 auto
    }

    .elementor-image-gallery figure img {
        display: block
    }

    .gallery-spacing-custom .elementor-image-gallery .gallery-icon {
        padding: 0
    }

    @media (min-width:768px) {
        .elementor-image-gallery .gallery-columns-6 .gallery-item {
            max-width: 16.666%
        }
    }

    @media (min-width:480px) and (max-width:767px) {
        .elementor-image-gallery .gallery.gallery-columns-6 .gallery-item {
            max-width: 50%
        }
    }

    @media (max-width:479px) {
        .elementor-image-gallery .gallery.gallery-columns-6 .gallery-item {
            max-width: 100%
        }
    }

