    button.pswp__button {
        box-shadow: none !important;
        background-image: var(--wpr-bg-3e1755e0-2e52-4e56-8f0d-81be9e11e619) !important
    }

    button.pswp__button,
    button.pswp__button--arrow--left::before,
    button.pswp__button--arrow--right::before {
        background-color: transparent !important
    }

    button.pswp__button--arrow--left,
    button.pswp__button--arrow--right {
        background-image: none !important
    }

    .pswp {
        display: none;
        position: absolute;
        width: 100%;
        height: 100%;
        left: 0;
        top: 0;
        overflow: hidden;
        -ms-touch-action: none;
        touch-action: none;
        z-index: 1500;
        -webkit-text-size-adjust: 100%;
        -webkit-backface-visibility: hidden;
        outline: 0
    }

    .pswp * {
        -webkit-box-sizing: border-box;
        box-sizing: border-box
    }

    .pswp__bg {
        position: absolute;
        left: 0;
        top: 0;
        width: 100%;
        height: 100%;
        background: #000;
        opacity: 0;
        -webkit-transform: translateZ(0);
        transform: translateZ(0);
        -webkit-backface-visibility: hidden;
        will-change: opacity
    }

    .pswp__scroll-wrap {
        position: absolute;
        left: 0;
        top: 0;
        width: 100%;
        height: 100%;
        overflow: hidden
    }

    .pswp__container {
        -ms-touch-action: none;
        touch-action: none;
        position: absolute;
        left: 0;
        right: 0;
        top: 0;
        bottom: 0
    }

    .pswp__container {
        -webkit-touch-callout: none
    }

    .pswp__bg {
        will-change: opacity
    }

    .pswp__container {
        -webkit-backface-visibility: hidden
    }

    .pswp__item {
        position: absolute;
        left: 0;
        right: 0;
        top: 0;
        bottom: 0;
        overflow: hidden
    }

    .pswp__button {
        width: 44px;
        height: 44px;
        position: relative;
        background: 0 0;
        overflow: visible;
        -webkit-appearance: none;
        display: block;
        border: 0;
        padding: 0;
        margin: 0;
        float: left;
        opacity: .75;
        -webkit-box-shadow: none;
        box-shadow: none
    }

    .pswp__button::-moz-focus-inner {
        padding: 0;
        border: 0
    }

    .pswp__button,
    .pswp__button--arrow--left:before,
    .pswp__button--arrow--right:before {
        background: var(--wpr-bg-63f2b8f3-c100-46fc-bb72-27ec7b296bf8) 0 0 no-repeat;
        background-size: 264px 88px;
        width: 44px;
        height: 44px
    }

    .pswp__button--close {
        background-position: 0 -44px
    }

    .pswp__button--share {
        background-position: -44px -44px
    }

    .pswp__button--fs {
        display: none
    }

    .pswp__button--zoom {
        display: none;
        background-position: -88px 0
    }

    .pswp__button--arrow--left,
    .pswp__button--arrow--right {
        background: 0 0;
        top: 50%;
        margin-top: -50px;
        width: 70px;
        height: 100px;
        position: absolute
    }

    .pswp__button--arrow--left {
        left: 0
    }

    .pswp__button--arrow--right {
        right: 0
    }

    .pswp__button--arrow--left:before,
    .pswp__button--arrow--right:before {
        content: '';
        top: 35px;
        background-color: rgba(0, 0, 0, .3);
        height: 30px;
        width: 32px;
        position: absolute
    }

    .pswp__button--arrow--left:before {
        left: 6px;
        background-position: -138px -44px
    }

    .pswp__button--arrow--right:before {
        right: 6px;
        background-position: -94px -44px
    }

    .pswp__share-modal {
        display: block;
        background: rgba(0, 0, 0, .5);
        width: 100%;
        height: 100%;
        top: 0;
        left: 0;
        padding: 10px;
        position: absolute;
        z-index: 1600;
        opacity: 0;
        -webkit-backface-visibility: hidden;
        will-change: opacity
    }

    .pswp__share-modal--hidden {
        display: none
    }

    .pswp__share-tooltip {
        z-index: 1620;
        position: absolute;
        background: #fff;
        top: 56px;
        border-radius: 2px;
        display: block;
        width: auto;
        right: 44px;
        -webkit-box-shadow: 0 2px 5px rgba(0, 0, 0, .25);
        box-shadow: 0 2px 5px rgba(0, 0, 0, .25);
        -webkit-transform: translateY(6px);
        -ms-transform: translateY(6px);
        transform: translateY(6px);
        -webkit-backface-visibility: hidden;
        will-change: transform
    }

    .pswp__counter {
        position: relative;
        left: 0;
        top: 0;
        height: 44px;
        font-size: 13px;
        line-height: 44px;
        color: #fff;
        opacity: .75;
        padding: 0 10px;
        margin-inline-end: auto
    }

    .pswp__caption {
        position: absolute;
        left: 0;
        bottom: 0;
        width: 100%;
        min-height: 44px
    }

    .pswp__caption__center {
        text-align: left;
        max-width: 420px;
        margin: 0 auto;
        font-size: 13px;
        padding: 10px;
        line-height: 20px;
        color: #ccc
    }

    .pswp__preloader {
        width: 44px;
        height: 44px;
        position: absolute;
        top: 0;
        left: 50%;
        margin-left: -22px;
        opacity: 0;
        will-change: opacity;
        direction: ltr
    }

    .pswp__preloader__icn {
        width: 20px;
        height: 20px;
        margin: 12px
    }

    @media screen and (max-width:1024px) {
        .pswp__preloader {
            position: relative;
            left: auto;
            top: auto;
            margin: 0;
            float: right
        }
    }

    .pswp__ui {
        -webkit-font-smoothing: auto;
        visibility: visible;
        opacity: 1;
        z-index: 1550
    }

    .pswp__top-bar {
        position: absolute;
        left: 0;
        top: 0;
        height: 44px;
        width: 100%;
        display: flex;
        justify-content: flex-end
    }

    .pswp__caption,
    .pswp__top-bar {
        -webkit-backface-visibility: hidden;
        will-change: opacity
    }

    .pswp__caption,
    .pswp__top-bar {
        background-color: rgba(0, 0, 0, .5)
    }

    .pswp__ui--hidden .pswp__button--arrow--left,
    .pswp__ui--hidden .pswp__button--arrow--right,
    .pswp__ui--hidden .pswp__caption,
    .pswp__ui--hidden .pswp__top-bar {
        opacity: .001
    }
</style>

