    /* Start custom CSS */
    .mobile-menu-btn {
        cursor: pointer;
        height: 100%;
        padding: 10px;
        align-items: center;
        justify-content: center;
        display: flex;
        /*background: #050505;*/
    }

    .mobile-menu-btn .bars {
        position: relative;
        display: block;
        width: 20px;
        height: 15px;
    }

    .mobile-menu-btn .line {
        transition: all 0.2s ease-out;
        background: #000;
        opacity: 1;
        height: 2px;
        border-radius: 4px;
        width: 100%;
        font-size: 0;
        left: 0;
        position: absolute;
        transform-origin: center center;
    }

    .mobile-menu-btn .line1 {
        top: 0;
    }

    .mobile-menu-btn .line2 {
        top: 50%;
        margin-top: -1.5px;
    }

    .mobile-menu-btn .line3 {
        top: 100%;
        margin-top: -3px;
    }

    .mobile-menu-btn:hover .line {
        opacity: 1;
    }

    body.show-mobile-menu {
        overflow: hidden;
    }

    /*body.show-mobile-menu .mobile-menu {*/
    /*    display: flex;*/
    /*}*/

    .show-mobile-menu .mobile-menu-btn .line {
        opacity: 1;
    }

    .show-mobile-menu .mobile-menu-btn .line1 {
        transform: rotate(45deg);
        top: 50%;
        margin-top: -1.5px;
    }

    .show-mobile-menu .mobile-menu-btn .line2 {
        opacity: 0;
    }

    .show-mobile-menu .mobile-menu-btn .line3 {
        transform: rotate(-45deg);
        top: 50%;
        margin-top: -1.5px;
    }

