                    data-id="b36181a" data-element_type="widget"
                    data-settings="{&quot;_ob_widget_stalker_use&quot;:&quot;no&quot;,&quot;_ob_poopart_use&quot;:&quot;yes&quot;,&quot;_ob_shadough_use&quot;:&quot;no&quot;,&quot;_ob_allow_hoveranimator&quot;:&quot;no&quot;}"
                    data-widget_type="html.default">
                    <div class="elementor-widget-container">
                        <script>
                            (function ($) {

                                // $(document).ready(function() {


                                $('.block-overflow:not(.elementor-element-edit-mode)').each(function (index, element) {
                                    var $content = $(element).find(".row-reviews");
                                    var $clone = $content.find('.elementor-widget-eael-testimonial').clone();
                                    $clone.addClass('clone');
                                    $(element).find(".row-reviews").append($clone);

                                    var direction = 1;

                                    if ($(element).hasClass('block-overflow-2')) {
                                        direction = -1;
                                        $(element).scrollLeft($(element).prop("scrollWidth"));
                                    }

                                    var speedNormal = 40 * direction;
                                    var speedSlow = 9 * direction;

                                    var position = 0;
                                    var speed = speedNormal;


                                    function animate() {
                                        if ($(window).width() >= 768) {

                                            position -= speed / 60; // 60 FPS

                                            if ($(element).hasClass('block-overflow-2')) {
                                                if (position >= $content.width() / 2) {
                                                    position = 0;
                                                }
                                            } else {
                                                if (position <= -$content.width() / 2) {
                                                    position = 0;
                                                }
                                            }
                                            $content.css("transform", `translateX(${position}px)`);

                                        }
                                        requestAnimationFrame(animate);
                                    }

                                    animate();

                                    $(element).hover(
                                        function () {
                                            speed = speedSlow;
                                        },
                                        function () {
                                            speed = speedNormal;
                                        }
                                    );

                                });


                                // });

                            })(jQuery);

                        </script>
                    </div>
                </div>
