                                    <h2 class="elementor-heading-title elementor-size-default">Author Gus Stefanow
                                    </h2>
                                </div>
                            </div>
                            <div data-dce-text-color="#292929"
                                class="elementor-element elementor-element-68fc7b64 ob-has-background-overlay elementor-widget elementor-widget-text-editor"
                                data-id="68fc7b64" data-element_type="widget"
                                data-settings="{&quot;_ob_postman_use&quot;:&quot;no&quot;,&quot;_ob_widget_stalker_use&quot;:&quot;no&quot;,&quot;_ob_poopart_use&quot;:&quot;yes&quot;,&quot;_ob_shadough_use&quot;:&quot;no&quot;,&quot;_ob_allow_hoveranimator&quot;:&quot;no&quot;}"
                                data-widget_type="text-editor.default">
                                <div class="elementor-widget-container">
                                    <p>&#8220;I waited for years to find a company like Spines that truly has my
                                        best interest at heart. No one in the publishing industry comes close to
                                        offering what they can. The value received from Spines is unbelievable. On a
                                        scale of 1 to 10, the company deserves an 11. Thank you.&#8221;</p>
                                </div>
                            </div>
