                                data-widget_type="text-editor.default">
                                <div class="elementor-widget-container">
                                    <p>&#8220;Spines delivered on all their promises, quickly, effectively, and
                                        productively. My production manager, Wardah, was wonderful and helped me at
                                        every step of the way. I would definitely publish with Spines again and
                                        recommend them to any author.&#8221;</p>
                                </div>
