                                <div class="elementor-widget-container">
                                    <h2 class="elementor-heading-title elementor-size-default">Author Yoav Magen
                                    </h2>
                                </div>
                            </div>
                            <div data-dce-text-color="#292929"
                                class="elementor-element elementor-element-78c1e549 ob-has-background-overlay elementor-widget elementor-widget-text-editor"
                                data-id="78c1e549" data-element_type="widget"
                                data-settings="{&quot;_ob_postman_use&quot;:&quot;no&quot;,&quot;_ob_widget_stalker_use&quot;:&quot;no&quot;,&quot;_ob_poopart_use&quot;:&quot;yes&quot;,&quot;_ob_shadough_use&quot;:&quot;no&quot;,&quot;_ob_allow_hoveranimator&quot;:&quot;no&quot;}"
                                data-widget_type="text-editor.default">
                                <div class="elementor-widget-container">
                                    <p>&#8220;When I first heard about Spines, I have to admit, it sounded too good
                                        to be true. However, when I realized that it&#8217;s not only a great
                                        publishing platform that uses AI, but also, at its core, driven by great
                                        people who push everything forward quickly and with very high quality, I was
                                        impressed. The book came out just as I wanted it to. Thank you so
                                        much.&#8221;</p>
                                </div>
                            </div>
                        </div>
